from solution import add_elements
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference(arr, k):
    """Obviously-correct model: digits ignoring sign, so |x| <= 99."""
    return sum(x for x in arr[:k] if abs(x) < 100)


def test_example_from_spec():
    assert add_elements([111, 21, 3, 4000, 5, 6, 7, 8, 9], 4) == 24


def test_two_digit_positive_boundary():
    # 99 has two digits -> included; 100 has three -> excluded; 111 excluded
    assert add_elements([99, 100, 111], 3) == 99


def test_single_digit_and_zero_included():
    assert add_elements([0, 3, 5, 9], 4) == 17
    assert add_elements([0], 1) == 0


def test_exactly_two_digits_included():
    assert add_elements([10, 21, 99, -10, -21, -99], 6) == 0
    assert add_elements([10, 21], 2) == 31


def test_three_digits_excluded_positive():
    assert add_elements([100, 111, 4000, 1000], 4) == 0


def test_large_negative_magnitude_excluded():
    # -100, -1000 have more than two digits, must not be summed.
    # Buggy `x < 100` includes them.
    assert add_elements([-100], 1) == 0
    assert add_elements([-1000], 1) == 0
    assert add_elements([-10000, -111, -100], 3) == 0


def test_mixed_negative_boundary():
    # -99 (two digits) included, -100 (three digits) excluded
    assert add_elements([-99, -100, 21, 111], 4) == -99 + 21


def test_only_first_k_elements_counted():
    arr = [21, 3, 5, 6, 7]
    assert add_elements(arr, 2) == 24
    assert add_elements(arr, 4) == 21 + 3 + 5 + 6
    # elements beyond k with <=2 digits must be ignored
    assert add_elements([111, 111, 111, 1], 3) == 0
    assert add_elements([111, 111, 111, 1], 4) == 1


def test_k_equals_len_and_k_equals_one():
    assert add_elements([111, 21, 3, 4000], 4) == 24
    assert add_elements([5], 1) == 5
    assert add_elements([111], 1) == 0
    assert add_elements([-1000], 1) == 0


@given(
    arr=st.lists(st.integers(min_value=-2000, max_value=2000), min_size=1, max_size=20),
    k=st.integers(min_value=1, max_value=20),
)
def test_equivalence_to_reference_model(arr, k):
    assume(1 <= k <= len(arr))
    assume(1 <= len(arr) <= 100)
    assert add_elements(arr, k) == reference(arr, k)


@given(arr=st.lists(st.integers(min_value=0, max_value=2000), min_size=1, max_size=15))
def test_all_three_digit_positive_sums_to_zero(arr):
    assume(all(x >= 100 for x in arr))
    assert add_elements(arr, len(arr)) == 0


@given(arr=st.lists(st.integers(min_value=-2000, max_value=-100), min_size=1, max_size=15))
def test_all_large_negative_sums_to_zero(arr):
    # every element has >= 3 digits, so sum must be 0
    assume(all(abs(x) >= 100 for x in arr))
    assert add_elements(arr, len(arr)) == 0


@given(
    arr=st.lists(st.integers(min_value=-99, max_value=99), min_size=1, max_size=15),
    k=st.integers(min_value=1, max_value=15),
)
def test_all_small_elements_sum_is_plain_sum(arr, k):
    assume(1 <= k <= len(arr))
    # all have <= 2 digits, so result is just sum of first k
    assert add_elements(arr, k) == sum(arr[:k])


@given(
    arr=st.lists(st.integers(min_value=-500, max_value=500), min_size=1, max_size=10),
    k=st.integers(min_value=1, max_value=10),
)
def test_permutation_of_first_k_preserves_sum(arr, k):
    assume(1 <= k <= len(arr))
    import random
    first = list(arr[:k])
    # deterministic permutation: reversed
    permuted = list(reversed(first)) + list(arr[k:])
    assert add_elements(permuted, k) == add_elements(arr, k)


@given(
    arr=st.lists(st.integers(min_value=-99, max_value=99), min_size=1, max_size=10),
    k=st.integers(min_value=1, max_value=10),
)
def test_adding_large_offset_excludes_element(arr, k):
    assume(1 <= k <= len(arr))
    base = add_elements(arr, k)
    # make first element large positive (>=1000, 4 digits) -> it must drop out
    modified = [arr[0] + 1000 if arr[0] >= 0 else arr[0] - 1000] + arr[1:]
    # original arr[0] was <=2 digits so was included; now excluded
    assert add_elements(modified, k) == base - arr[0]
